function nsApplyDeco(face,p,quiet){
  if(!face) return;
  face.querySelectorAll(":scope > .nsd").forEach(n=>n.remove()); face.classList.remove("nsd-host","nsd-blend","nsd-only");
  const ns=nsOf(p), a=ns.deco&&NS_DECO_ART[ns.deco]; if(!a) return;
  const art=quiet&&a.q?a.q:a, n=++nsdSeq;
  face.classList.add("nsd-host",ns.blend==="deco"?"nsd-only":"nsd-blend");
  ["back","front"].forEach(layer=>{ if(!art[layer]) return; const w=document.createElement("span"); w.className="nsd nsd-"+layer[0]+(quiet?" quiet":""); w.append(nsDecoSvg(art[layer],n)); face.append(w); });
}
/* every face in the app goes through paintFace, so decorations follow you everywhere */
const _nsdPaintFace=paintFace;
paintFace=function(node,p){
  const keep=[...node.querySelectorAll(":scope > .nsd")], oldKey=node.dataset.nsdKey;
  _nsdPaintFace(node,p);
  const quiet=!node.classList.contains("lg"), ns=nsOf(p), key=(ns.deco||"")+"|"+quiet+"|"+ns.blend;
  if(key===oldKey&&keep.length){ keep.forEach(k=>node.append(k)); return; }   // same decoration as before: keep it running instead of restarting it
  try{ nsApplyDeco(node,p,quiet); }catch(e){}
  node.dataset.nsdKey=key;
};
